"use client";

import { useState, useEffect, useTransition } from "react";
import { usePageTitle } from "@/lib/hooks/use-page-title";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import NextLink from "next/link";
import { ArrowLeft, FileOutput, ExternalLink, Download } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { listOutputFeeds, type OutputFeed } from "@/lib/mellis-actions";

export default function ManageExportPage() {
  usePageTitle("Threat Feeds: Manage Export files");
  const [outputFeeds, setOutputFeeds] = useState<OutputFeed[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  useEffect(() => {
    startTransition(async () => {
      try {
        const res = await listOutputFeeds();
        setOutputFeeds(res.data);
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load output feeds");
      } finally {
        setLoading(false);
      }
    });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const legacyFeeds = outputFeeds.filter((f) => f.legacy_filename);

  return (
    <div className="flex flex-col gap-6 max-w-4xl">
      <NextLink href="/threat-feeds">
        <Button variant="ghost" size="sm" className="gap-1">
          <ArrowLeft className="h-4 w-4" aria-hidden />
          Back to Threat Feeds
        </Button>
      </NextLink>

      <h1 className="text-xl font-bold text-left">Manage Export files</h1>
      <p className="text-muted-foreground">
        Configure output feed parameters for Firewall/IDP integration. Output feeds are generated by mellis and served as plaintext files on the legacy feed port (9000).
      </p>

      {error && (
        <p className="text-sm text-destructive" role="alert">{error}</p>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileOutput className="h-5 w-5" aria-hidden />
            Output Feeds
          </CardTitle>
          <CardDescription>
            Configured output feeds and their export parameters.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <p className="text-sm text-muted-foreground">Loading output feeds...</p>
          ) : outputFeeds.length === 0 ? (
            <p className="text-sm text-muted-foreground">No output feeds configured.</p>
          ) : (
            <div className="border rounded-md overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>ID</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Format</TableHead>
                    <TableHead>Max Entries</TableHead>
                    <TableHead>Min Score</TableHead>
                    <TableHead>Refresh (s)</TableHead>
                    <TableHead>Legacy File</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {outputFeeds.map((feed) => (
                    <TableRow key={feed.id}>
                      <TableCell className="font-mono">{feed.id}</TableCell>
                      <TableCell>{feed.name}</TableCell>
                      <TableCell>{feed.format}</TableCell>
                      <TableCell>{feed.max_entries.toLocaleString()}</TableCell>
                      <TableCell>{feed.min_score}</TableCell>
                      <TableCell>{feed.refresh_interval}</TableCell>
                      <TableCell className="font-mono">{feed.legacy_filename ?? "\u2014"}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {legacyFeeds.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Download className="h-5 w-5" aria-hidden />
              Legacy Feed Downloads (port 9000)
            </CardTitle>
            <CardDescription>
              Plaintext feed files served on port 9000 for backward compatibility with chn-intel-feeds consumers (e.g. Palo Alto EDL, Cisco Firepower SI Lists).
            </CardDescription>
          </CardHeader>
          <CardContent className="flex flex-col gap-2">
            {legacyFeeds.map((feed) => (
              <div key={feed.id} className="flex items-center gap-3">
                <span className="font-mono text-sm">{feed.legacy_filename}</span>
                <Button variant="outline" size="sm" className="gap-1" asChild>
                  <a
                    href={`/feeds/${feed.legacy_filename}`}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <ExternalLink className="h-3 w-3" aria-hidden />
                    Open
                  </a>
                </Button>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileOutput className="h-5 w-5" aria-hidden />
            Local indicators endpoint
          </CardTitle>
          <CardDescription>
            For sites without CIF, you can use the local indicators API to consume threat data (e.g. Palo Alto EDL, Cisco Firepower SI Lists).
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-2">
          <p className="text-sm font-mono text-muted-foreground break-all">
            /api/v2/indicators
          </p>
          <Button variant="outline" size="sm" className="w-fit gap-1" asChild>
            <NextLink href="/api/v2/indicators" target="_blank" rel="noopener noreferrer">
              <ExternalLink className="h-4 w-4" aria-hidden />
              Open indicators endpoint (new tab)
            </NextLink>
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}
